SE_01 = 1035; --気を貯める
SE_02 = 1036; --気が広がる
SE_03 = 1036; --かめはめ
SE_04 = 1018; --カットイン
SE_05 = 1035; --カットイン攻撃
SE_06 = 1021; --発射
SE_07 = 1022; --のびる発射
SE_08 = 1042; --カットイン
SE_09 = 1023; --HIT
SE_10 = 1024; --爆破
SE_11 = 1054; --割れる音
SE_12 = 09;

--味方側
SP_01 = 161292; --ドーナツ発射  ef_001
SP_02 = 161294; --ドーナツが敵をボールにする ef_002_front
SP_03 = 161295; --ドーナツが敵をボールにする ef_002_back
SP_04 = 161298; --いくわよ～ボール打ち上げ～トス  ef_003
SP_05 = 161300; --アタック～ボール落下～フィニッシュ  ef_004

--敵側
SP_01r = 161293; --ドーナツ発射　ef_001_r
SP_02r = 161296; --ドーナツが敵をボールにする ef_002_r_front
SP_03r = 161297; --ドーナツが敵をボールにする ef_002_r_back
SP_04r = 161299; --いくわよ～ボール打ち上げ～トス ef_003_r
SP_05r = 161301; --アタック～ボール落下～フィニッシュ  ef_004_r


------------------------------------------------------
-- テンプレ構文
------------------------------------------------------

multi_frm = 2;

setVisibleUI( 0, 0);

changeAnime( 0, 0, 0);
changeAnime( 0, 1, 100);
setDisp( 0, 0, 0);
setDisp( 0, 1, 0);

setMoveKey(   0,   0,    0, -5000,   0);
setMoveKey(   1,   0,    0, -5000,   0);
setMoveKey(   2,   0,    0, -5000,   0);
setMoveKey(   3,   0,    0, -5000,   0);
setMoveKey(   4,   0,    0, -5000,   0);
setMoveKey(   5,   0,    0, -5000,   0);
setMoveKey(   6,   0,    0, -5000,   0);
setScaleKey(  0,   0,  1.6, 1.6 );
setScaleKey(  1,   0,  1.6, 1.6 );
setScaleKey(  2,   0,  1.6, 1.6 );
setScaleKey(  3,   0,  1.6, 1.6 );
setScaleKey(  4,   0,  1.6, 1.6 );
setScaleKey(  5,   0,  1.6, 1.6 );
setScaleKey(  6,   0,  1.6, 1.6 );
setRotateKey( 0,   0,  0 );
